-- Standalone disposable database fixture; never run in an application database.
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
 SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid
$$;
CREATE TABLE public.organizations(id bigint PRIMARY KEY,title text);
CREATE TABLE public.occasions(id bigint PRIMARY KEY,organization bigint);
CREATE TABLE public.news(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 occasion bigint,message text,created_by uuid);
ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.get_is_editor_on_occasion(bigint) RETURNS boolean
LANGUAGE sql STABLE AS $$ SELECT auth.uid()='00000000-0000-0000-0000-000000000001'::uuid $$;
CREATE POLICY "Enable insert for editors" ON public.news FOR INSERT
TO authenticated WITH CHECK(public.get_is_editor_on_occasion(occasion));
